            valid := FALSE;
            EXIT;
        END_IF;
    END_FOR;
    IF NOT valid THEN
        ipValue := 0;
        RETURN;
    END_IF;
    val1 := TO_UDINT(seg1);
    IF val1 > 255 THEN
        ipValue := 0;
        RETURN;
    END_IF;

