        IF charVal < 48 OR charVal > 57 THEN
            valid := FALSE;
            EXIT;
        END_IF;
    END_FOR;
    IF NOT valid THEN
        ipValue := 0;
        RETURN;
    END_IF;
    val2 := TO_UDINT(seg2);
    IF val2 > 255 THEN
        ipValue := 0;
        RETURN;
    END_IF;

    // Segment 3: positions dotPos2+1 to dotPos3-1
    segLen := dotPos3 - dotPos2 - 1;
    IF segLen < 1 OR segLen > 3 THEN
        ipValue := 0;
        RETURN;
    END_IF;
    seg3 := MID(ipText, segLen, dotPos2 + 1);
    valid := TRUE;
    FOR i := 1 TO segLen DO
        charVal := TO_BYTE(MID(seg3, 1, i));
        IF charVal < 48 OR charVal > 57 THEN
            valid := FALSE;
            EXIT;
        END_IF;
    END_FOR;
    IF NOT valid THEN
        ipValue := 0;
        RETURN;
    END_IF;
    val3 := TO_UDINT(seg3);
    IF val3 > 255 THEN
        ipValue := 0;
        RETURN;
    END_IF;

    // Segment 4: positions dotPos3+1 to end
    segLen := textLen - dotPos3;
    IF segLen < 1 OR segLen > 3 THEN
        ipValue := 0;
        RETURN;
    END_IF;
    seg4 := MID(ipText, segLen, dotPos3 + 1);
    valid := TRUE;
    FOR i := 1 TO segLen DO
        charVal := TO_BYTE(MID(seg4, 1, i));
        IF charVal < 48 OR charVal > 57 THEN
            valid := FALSE;
            EXIT;
        END_IF;
    END_FOR;
    IF NOT valid THEN
        ipValue := 0;
        RETURN;
    END_IF;
    val4 := TO_UDINT(seg4);
    IF val4 > 255 THEN
        ipValue := 0;
        RETURN;
    END_IF;

    // PUB003: Assemble in network byte order (MSB first)
    ipValue := SHL(val1, 24) OR SHL(val2, 16) OR SHL(val3, 8) OR val4;

END_FUNCTION_BLOCK

